```javascript
import {
  Group,
  Mesh,
  PlaneGeometry,
  BoxGeometry,
  Color,
  DirectionalLight
} from 'three/webgpu';
import {
  MeshStandardNodeMaterial
} from 'three/webgpu';
import {
  uv,
  mix,
  vec3
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  const bandWidth = 6.8;
  const bandHeight = 2.0;

  const group = new Group();

  // --- band plane with gradient ---
  const bandGeo = new PlaneGeometry(bandWidth, bandHeight);
  const bandMat = new MeshStandardNodeMaterial({
    roughness: 0.6,
    metalness: 0.2,
    side: THREE.DoubleSide
  });

  const colorBottom = new Color('#121218');
  const colorTop = new Color('#0b0b10');
  bandMat.colorNode = mix(
    vec3(colorBottom.r, colorBottom.g, colorBottom.b),
    vec3(colorTop.r, colorTop.g, colorTop.b),
    uv().y   // 0 at bottom, 1 at top
  );
  const bandMesh = new Mesh(bandGeo, bandMat);
  bandMesh.position.z = 0;
  group.add(bandMesh);

  // --- directional light from upper left (grazing light) ---
  const keyLight = new DirectionalLight(0xffffff, 1.0);
  keyLight.position.set(3, 3, 5);
  keyLight.target.position.set(0, 0, 0);
  group.add(keyLight);
  group.add(keyLight.target);

  // --- top hairline rule ---
  const hairlineGeo = new BoxGeometry(bandWidth, 0.006, 0.01);
  const hairlineMat = new MeshStandardNodeMaterial({
    color: new Color('#23232b'),
    roughness: 0.6,
    metalness: 0.2
  });
  const topHair = new Mesh(hairlineGeo, hairlineMat);
  topHair.position.set(0, bandHeight / 2 - 0.003, 0.005);
  group.add(topHair);

  // --- bottom hairline rule ---
  const bottomHair = new Mesh(hairlineGeo.clone(), hairlineMat.clone());
  // Spec: 0.25 clearance above bottom edge
  bottomHair.position.set(0, -bandHeight / 2 + 0.25 + 0.003, 0.005);
  group.add(bottomHair);

  // --- accent bar ---
  const accentGeo = new BoxGeometry(0.3, 0.02, 0.01);
  const accentMat = new MeshStandardNodeMaterial({
    color: new Color('#ff2a38'),
    emissive: new Color('#ff2a38'),
    emissiveIntensity: 1.4,
    roughness: 0.5,
    metalness: 0.2
  });
  const accentBar = new Mesh(accentGeo, accentMat);
  accentBar.position.set(-bandWidth / 2 + 1.0, 0.68, 0.005);
  group.add(accentBar);

  // --- text layout ---
  const leftBlockX = -bandWidth / 2 + 0.5; // -2.9
  const wordmarkY = 0.8;
  const colXPositions = [-1.4, 0.175, 1.75];
  const colHeaderY = 0.5;
  // Font sizes in scene units (em heights)
  const fontSizeWordmark = 0.62;
  const fontSizeColumnHeader = 0.09;
  const fontSizeLink = 0.13;
  const fontSizeLegal = 0.09;
  const linkStep = fontSizeLink * 1.8; // line height

  const roleConfig = {
    wordmark: { fontSize: fontSizeWordmark, letterSpacing: 0.02, align: 'left', color: '#e8ecf2' },
    'column-header': { fontSize: fontSizeColumnHeader, letterSpacing: 0.12, align: 'left', color: '#e8ecf2' },
    link: { fontSize: fontSizeLink, letterSpacing: 0, align: 'left', color: '#e8ecf2' },
    legal: { fontSize: fontSizeLegal, letterSpacing: 0.04, align: 'center', color: '#e8ecf2' }
  };

  let colIndex = -1;
  let linkIndex = 0;
  const linkObjects = [];

  const isHoverable = (role) => role === 'link';

  items.forEach((item) => {
    const role = item.role;
    const text = item.text;
    const cfg = roleConfig[role];
    if (!cfg) return;

    const textObj = ctx.fontAtlas.createText(text, {
      fontSize: cfg.fontSize,
      letterSpacingPx: cfg.letterSpacing,
      align: cfg.align,
      color: cfg.color,
      maxWidthPx: (role === 'wordmark' || role === 'legal') ? bandWidth : 1.2
    });

    if (role === 'wordmark') {
      textObj.position.set(leftBlockX, wordmarkY, 0.005);
    } else if (role === 'column-header') {
      colIndex++;
      linkIndex = 0;
      textObj.position.set(colXPositions[colIndex], colHeaderY, 0.005);
    } else if (role === 'link') {
      const x = colXPositions[colIndex];
      const y = colHeaderY - fontSizeColumnHeader * 1.2 - (linkIndex + 1) * linkStep;
      textObj.position.set(x, y, 0.005);
      linkIndex++;
      linkObjects.push(textObj);
    } else if (role === 'legal') {
      textObj.position.set(0, -0.625, 0.005);
    }

    group.add(textObj);
  });

  // --- link hover interactions ---
  const linkTimelines = [];
  linkObjects.forEach((obj) => {
    const originalColor = '#e8ecf2';
    const hoverColor = '#ff2a38';
    // Store the children meshes and their materials
    const meshes = [];
    obj.traverse(child => {
      if (child.isMesh) {
        meshes.push(child);
        child.material.transparent = true;
        child.material.needsUpdate = true;
      }
    });

    const onEnter = () => {
      if (linkTimelines[obj.uuid]) {
        linkTimelines[obj.uuid].kill();
      }
      const tl = gsap.to(
        meshes.map(m => m.material.color),
        { r: new Color(hoverColor).r, g: new Color(hoverColor).g, b: new Color(hoverColor).b, duration: 0.14, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)', overwrite: true }
      );
      gsap.to(obj.position, { z: 0.02, duration: 0.14, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)', overwrite: true });
      linkTimelines[obj.uuid] = tl;
    };

    const onLeave = () => {
      if (linkTimelines[obj.uuid]) {
        linkTimelines[obj.uuid].kill();
      }
      const tl = gsap.to(
        meshes.map(m => m.material.color),
        { r: new Color(originalColor).r, g: new Color(originalColor).g, b: new Color(originalColor).b, duration: 0.14, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)', overwrite: true }
      );
      gsap.to(obj.position, { z: 0, duration: 0.14, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)', overwrite: true });
      linkTimelines[obj.uuid] = tl;
    };

    obj.userData.handlers = {
      pointerenter: onEnter,
      pointerleave: onLeave
    };
  });

  // --- entrance animation: fade-up of whole colophon ---
  // Gather all materials that need opacity animation
  const allMaterials = [];
  group.traverse(child => {
    if (child.isMesh && child.material) {
      child.material.transparent = true;
      child.material.needsUpdate = true;
      allMaterials.push(child.material);
    }
  });

  // Start invisible and displaced
  allMaterials.forEach(mat => { mat.opacity = 0; });
  group.position.y = 0.2;

  const enterTL = gsap.timeline({
    paused: true,
    onComplete: () => {
      // Ensure full opacity after animation
      allMaterials.forEach(mat => { mat.opacity = 1; });
      group.position.y = 0;
    }
  });
  enterTL.to(allMaterials.map(mat => ({ obj: mat, prop: 'opacity' })), {
    opacity: 1,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    stagger: 0,
    onUpdate: function () {
      // gsap applies to each element's property directly
    }
  }, 0);
  enterTL.to(group.position, {
    y: 0,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
  }, 0);
  enterTL.play();

  // --- cleanup ---
  const disposeList = [
    bandGeo, bandMat, bandMesh,
    hairlineGeo, topHair, bottomHair,
    accentGeo, accentMat, accentBar,
    ...group.children.filter(c => c.geometry && c.geometry !== bandGeo && c.geometry !== hairlineGeo && c.geometry !== accentGeo)
  ];

  group.userData.cleanup = () => {
    enterTL.kill();
    Object.values(linkTimelines).forEach(tl => tl && tl.kill());
    // Remove the light to prevent issues
    group.remove(keyLight);
    group.remove(keyLight.target);
    disposeList.forEach(obj => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) obj.material.dispose();
      if (obj.children) {
        obj.traverse(child => {
          if (child.geometry) child.geometry.dispose();
          if (child.material) child.material.dispose();
        });
      }
    });
  };

  return group;
}
